service.method:

SELECT
	DEPT
FROM
	SDEPT
WHERE
		HOUSE_CODE 		= ${HOUSE_CODE}
	AND COMPANY_CODE 	= ${COMPANY_CODE}	
	AND DEPT 			= ${DEPT}


UPDATE SDEPT
	SET	
		  DEPT 			  = ${DEPT}
		, DEPT_NAME_LOC	  = ${DEPT_NAME_LOC}
		, PARENT_DEPT	  = ${PARENT_DEPT}
		, DEL_FLAG		  = ${DEL_FLAG}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}
WHERE
		HOUSE_CODE        = ${HOUSE_CODE}
		AND COMPANY_CODE  = ${COMPANY_CODE}
		AND DEPT		  = ${DEPT}


INSERT INTO SDEPT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, DEPT
		, DEPT_NAME_LOC
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID				
		, PARENT_DEPT
		, DEL_FLAG
	)
	VALUES
	(
		  ${HOUSE_CODE}
		, ${COMPANY_CODE}
		, ${DEPT}
		, ${DEPT_NAME_LOC}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${PARENT_DEPT}
		, ${DEL_FLAG}
	)
